    "LXキューの呼び名を、照明デザイン・タイムライン・Qシート・進行表で通し番号（Q1・Q1.5）にそろえました。照明デザインに無いライトキューは「Q—（未登録）」と出ます。環境設定の「ショーごとの設定」で、シーンごと（1.2.2）にも切り替えられます。": "LX 큐 이름을 조명 디자인·타임라인·Q시트·진행표에서 일련번호(Q1·Q1.5)로 통일했습니다. 조명 디자인에 없는 라이트 큐는 ‘Q— (미등록)’으로 표시됩니다. 환경 설정의 ‘공연별 설정’에서 씬별(1.2.2)로도 바꿀 수 있습니다.",
    "照明デザイン: LXキューの一覧を、1本ずつ枠で囲んだ札にしました（番号・時間・名前・きっかけ・次へ自動）。直している札は錆色で、「次へ」と「後ろに入れる」はその札にだけ出ます。パネルの高さが足りないときはパネルごと巻け、〈LXキューを適用〉は下端に残ります。": "조명 디자인: LX 큐 목록을 하나씩 테두리로 둘러싼 카드로 바꿨습니다(번호·시간·이름·트리거·다음으로 자동). 수정 중인 카드는 녹슨 쇠 색이며, ‘다음’과 ‘이 뒤에 넣기’는 그 카드에만 나타납니다. 패널 높이가 부족하면 패널 전체가 스크롤되고, 〈LX 큐를 공연에 적용〉은 아래쪽에 남습니다.",
