    "アリーナ・ドームなど大きい劇場の3Dカメラで、遠くの客席を簡単に描いて動きを軽くする。近くの見え方は変わりません": "아레나·돔 등 큰 극장의 3D 카메라에서 멀리 있는 객석을 단순하게 그려 동작을 가볍게 합니다. 가까운 곳의 모습은 바뀌지 않습니다",
