    "演出意図のスケッチです。実施方法と安全は、劇場・照明担当者・専門家へ確認してください。": "연출 의도를 그린 스케치입니다. 실행 방법과 안전성은 극장·조명 담당자·관련 전문가에게 확인해 주세요.",
