  "下書き — まだ保存していません": "초안 — 아직 저장되지 않았습니다",
  "変更を保存しています…": "변경 내용을 저장하는 중…",
  "この端末へ保存できませんでした。ファイルへ書き出して残してください。": "이 기기에 저장하지 못했습니다. 파일로 내보내서 보관하세요.",
  "削除したものは元に戻せません。": "삭제한 항목은 되돌릴 수 없습니다.",
  "削除することを確認しました": "삭제를 확인했습니다",
