  "前の採用案から、表示中の案への転換を試します": "앞서 채택한 안에서 현재 표시된 안으로 전환을 미리 봅니다",
  "シーン転換の移動に、足を着いて歩く動きを追加しました。停止中は設定した姿勢を保ちます。": "씬 전환 중 이동에 발을 딛고 걷는 동작을 추가했습니다. 멈춰 있을 때는 설정한 자세를 유지합니다.",
  "正面図・3D・照明デザインで、同じ人体の形を使います。": "정면도·3D·조명 디자인에서 같은 인체 형태를 사용합니다.",
