  "● 舞台上　→ 動線あり　◆ 持ち物の変化　☀ 明かり　♪ 音　⚙ 機構": "● 무대 위　→ 동선 있음　◆ 소지품 변화　☀ 조명　♪ 소리　⚙ 무대 장치",
