  "Qシートを開けませんでした。ポップアップの許可を確認してください。": "Q시트를 열지 못했습니다. 팝업 허용 설정을 확인하세요.",
  "キューシートを印刷用の窓で開きました。": "Q시트를 인쇄용 창에서 열었습니다.",
