  "劇場カスタム": "극장 사용자 설정",
  "劇場カスタムモード": "극장 사용자 설정 모드",
  "舞台機構の追加、既製プリセット、シーンごとの状態をここで確認・変更します。": "여기서 무대 장치를 추가하고, 프리셋을 사용하며, 씬별 상태를 확인하거나 바꿉니다.",
  "上へドラッグするとタイムラインが広がります。上下キーで調整、ダブルクリックで元の高さに戻します": "위로 드래그하면 타임라인이 넓어집니다. 위아래 방향키로 조정하고 더블클릭하면 원래 높이로 돌아갑니다.",
  "表示する図。正面または平面": "표시할 도면: 정면도 또는 평면도",
  "タイミング未設定・仮の間隔で表示": "타이밍 미설정 · 임시 간격으로 표시",
