  "この客席範囲を選択しました。ドラッグで動かせます。": "이 객석 범위를 선택했습니다. 드래그해 옮길 수 있습니다.",
  "この客席範囲を選択しました。辺のタップで範囲を追加・解除できます。": "이 객석 범위를 선택했습니다. 무대의 변을 탭해 범위를 추가하거나 해제할 수 있습니다.",
  "この客席範囲を選択しました。": "이 객석 범위를 선택했습니다.",
  "四角の追加ステージを選択しました。ドラッグで動かせます。": "사각형 추가 무대를 선택했습니다. 드래그해 옮길 수 있습니다.",
  "丸の追加ステージを選択しました。ドラッグで動かせます。": "원형 추가 무대를 선택했습니다. 드래그해 옮길 수 있습니다.",
  "合成済みの追加ステージは一体の舞台面です。戻すと合成前にできます。": "합친 추가 무대는 하나의 무대 면입니다. 실행 취소하면 합치기 전으로 돌아갑니다.",
  "バックスクリーンを選択しました。左の長さ欄または端点で調整できます。": "배경 스크린을 선택했습니다. 왼쪽의 길이 칸이나 끝점으로 조정할 수 있습니다.",
  "選択した四角を削除": "선택한 사각형 삭제",
