  "横へドラッグして調整。押すと鍵を閉じます": "좌우로 드래그해 조정합니다. 누르면 잠급니다",
  "横へドラッグして調整。押すと丸へ戻します": "좌우로 드래그해 조정합니다. 누르면 설정 전의 동그라미로 돌아갑니다",
  "まとまりの頭に近い位置で押してください": "구간의 시작에 가까운 곳에서 눌러 주세요",
  "丸 → 閉じた鍵 → 開いた鍵。開いた鍵は横へドラッグして時刻を合わせます": "동그라미 → 잠긴 자물쇠 → 열린 자물쇠 순서로 바뀝니다. 열린 자물쇠를 좌우로 드래그해 시각을 맞춥니다",
