  "ドラッグで高さを変更。上下キーで調整、ダブルクリックまたはEnterで元に戻す": "드래그해 높이를 바꿉니다. 상하 방향키로 조정하고, 더블클릭하거나 Enter를 누르면 원래대로 돌아갑니다",
