  "まだ誰も登録していません。名前を入れて追加してください。": "아직 등록된 출연자가 없습니다. 이름을 입력해 추가해 주세요.",
  "モデルがありません": "모델이 없습니다",
  "まだ何も登録していません。名前と形を選んで追加してください。": "아직 등록된 항목이 없습니다. 이름과 형태를 선택해 추가해 주세요.",
  "まだ登録していません。種類を選び、名前を入れて追加してください。": "아직 등록된 조명이 없습니다. 종류와 이름을 입력해 추가해 주세요.",
