  "この組を外す": "이 묶음 제거",
  "ショー一覧の更新を止めています": "공연 목록의 업데이트가 일시 중지되었습니다",
  "ショー一覧を作り直す": "공연 목록 다시 만들기",
  "先にセットを組んでください": "먼저 무대 장치를 구성해 주세요",
  "まだ残していません。並べ終えたら名前をつけて残してください。小道具や家具を一つずつ登録するのは「演者・大道具」からです。": "아직 저장한 무대 장치가 없습니다. 배치를 마치면 이름을 붙여 저장해 주세요. 소품이나 가구를 하나씩 등록하려면 ‘출연자 · 무대 장치’에서 진행하세요.",
  "このショーの最初の版です。": "이 공연의 첫 번째 버전입니다.",
