  "感想の送り先（フォーム）はまだ用意できていません。いまは直接お知らせください。": "의견을 보내는 양식은 아직 준비되지 않았습니다. 지금은 제작자에게 직접 알려 주세요.",
  "舞台スケッチ": "무대 스케치",
  "β版": "베타 버전",
  "劇場形式を選び、カスタムステージを制作する": "극장 형식을 선택하고 맞춤형 무대를 만듭니다",
  "劇場形式プリセット": "극장 형식 프리셋",
  "この舞台に出る演者を登録します。姿勢・寸法・色はここで決め、シーンごとに舞台の上か裏かを切り替えます。追加した演者は、そのシーンの舞台に出ます。": "이 무대에 나올 출연자를 등록합니다. 여기에서 자세·치수·색을 정하고 씬마다 무대 위 또는 뒤에 둘지 선택합니다. 새로 추가한 출연자는 현재 씬의 무대에 배치됩니다.",
  "舞台に置く大道具を登録します。寸法や色はここで決め、追加したものはそのシーンの舞台に出ます。": "무대에 놓을 대도구를 등록합니다. 여기에서 치수와 색을 정하면 새 항목이 현재 씬의 무대에 배치됩니다.",
  "舞台に置く小道具を登録します。形・寸法・色はここで決め、追加したものはそのシーンの舞台に出ます。": "무대에 놓을 소품을 등록합니다. 여기에서 형태·치수·색을 정하면 새 항목이 현재 씬의 무대에 배치됩니다.",
  "大道具はまだありません。劇場設定で舞台機構を追加してください。": "아직 무대 장치가 없습니다. 극장 설정에서 무대 기계를 추가해 주세요.",
