  "キューシートを開きます。表ごとに「印刷」「CSV」で書き出せます。": "Q시트를 엽니다. 표마다 「인쇄」「CSV」로 내보낼 수 있습니다.",
  "Qシートを開き、表ごとに「印刷」「CSV」で書き出します。": "Q시트를 열어 표마다 「인쇄」「CSV」로 내보냅니다.",
