  "劇場設定の未適用の編集は破棄されます。作りかけのショーは一覧に残します。前のショーへ戻りますか？": "적용하지 않은 극장 설정 편집은 버려집니다. 만들던 공연은 목록에 남깁니다. 이전 공연으로 돌아갈까요?",
  "劇場設定の未適用の編集は破棄されます。いまのショーは一覧に残します。別のショーを開きますか？": "적용하지 않은 극장 설정 편집은 버려집니다. 지금 공연은 목록에 남깁니다. 다른 공연을 열까요?",
