  "盆・可動デッキ・幕・せりなど、シーンごとに動く舞台機構を置く欄を出す": "회전무대·이동식 데크·막·승강무대 등 씬마다 움직이는 무대 기계를 배치할 패널을 표시합니다",
  "大道具の並びを保存パネル": "무대 장치 저장 패널",
  "いまの舞台装置の並びに名前をつけて残し、別のシーンで呼び出す欄を出す": "현재 무대 장치 배치에 이름을 붙여 저장하고 다른 씬에서 불러올 패널을 표시합니다",
  "背景パネル": "배경 패널",
  "背景の地の色・塗る色・筆の太さなど、背景を描く欄を出す": "배경 바탕색·칠할 색·붓 굵기 등을 설정하는 배경 그리기 패널을 표시합니다",
  "パネルの表示スタイル": "패널 표시 방식",
  "下部・二図横並び": "두 도면 나란히 · 아래 패널",
  "正面・平面": "정면 · 평면",
