  "表示する図。二図の名前は左から右の順": "표시할 도면. 이름은 왼쪽에서 오른쪽 순서입니다",
  "下部・二図横並びでは図の下にパネルを並べます。2列・3列表示では図の左右へ、1列表示では一方の列へ並べます。": "두 도면 아래에 패널을 배치합니다. 2열·3열 표시는 도면 양옆에, 1열 표시는 한쪽에 패널을 배치합니다.",
