  "図を全画面表示（F）。矢印キーでシーン送り、FまたはEscで戻る": "도면을 전체 화면으로 표시합니다(F). 방향키로 씬을 넘기고 F 또는 Esc로 돌아갑니다",
  "全画面表示": "전체 화면 보기",
  "上部の「全画面」またはFキーで図を全画面に。右下の小窓で正面と平面を入れ替えられます": "위쪽의 ‘전체 화면’ 또는 F 키로 도면을 전체 화면으로 봅니다. 오른쪽 아래의 작은 창에서 정면도와 평면도를 바꿀 수 있습니다",
  "全画面の説明": "전체 화면 설명",
  "照明の光だまり": "조명 빛 영역",
  "明かりの見え方": "조명 표시 방식",
  "切（いまの概略）": "끔(현재의 간략 표시)",
  "光だまり": "빛 영역",
  "＋光の筋": "+ 빛줄기",
  "本番の暗さ": "공연 때의 어둠",
  "シーンのキューで点いている灯体の見え方。下の段ほど図が重くなります。「本番の暗さ」は作業灯を消して、光の当たる所だけを見せます": "씬의 큐에서 켜진 조명기구가 어떻게 표시되는지 정합니다. 아래 단계일수록 도면 처리에 더 많은 자원이 듭니다. ‘공연 때의 어둠’은 작업등을 끄고 빛이 닿는 곳만 보여 줍니다",
  "「照明の光だまり」を出しているとき、灯体から落ちる場所まで伸びる光の帯も出す。さらに重くなります": "‘조명 빛 영역’을 표시할 때 조명기구에서 빛이 닿는 곳까지 이어지는 빛의 띠도 표시합니다. 처리 부담이 더 커집니다",
  "照明の光の筋": "조명 빛줄기",
  "「照明の光だまり」を出しているとき、光の当たっていない所を暗くする。正面図・平面図・3Dカメラのすべてに効きます": "‘조명 빛 영역’을 표시할 때 빛이 닿지 않는 곳을 어둡게 합니다. 정면도·평면도·3D 카메라에 모두 적용됩니다",
  "全画面表示で、絵の下にシーン名と説明を出す": "전체 화면에서 도면 아래에 씬 이름과 설명을 표시합니다",
  "シーンのキューで点いている灯体の、光が落ちる場所を正面図・平面図に出す。図が重くなります": "씬의 큐에서 켜진 조명기구의 빛이 닿는 곳을 정면도와 평면도에 표시합니다. 도면 처리 부담이 커집니다",
  "前のシーンへ": "이전 씬으로",
  "次のシーンへ": "다음 씬으로",
  "全画面を終了": "전체 화면 종료",
  "文字サイズ": "글자 크기",
  "小": "작게",
  "中": "보통",
  "大": "크게",
  "暗転で始まるシーン": "암전으로 시작하는 씬",
  "シーンの欄に「暗転」の印が出て、その転換は一度真っ暗になってから明ける": "씬 항목에 ‘암전’ 표시가 나타나며, 전환 중에 완전히 어두워졌다가 다시 밝아집니다",
  "シーンの時間": "씬 시간",
  "各シーンに「見せる時間」と「次のシーンへの移動時間」を表示する": "각 씬에 ‘보여 주는 시간’과 ‘다음 씬으로 이동하는 시간’을 표시합니다",
  "シーンのサブタイトル": "씬 부제",
  "シーン一覧に構成上の役割をサブタイトルとして表示する。OFFでも内容は消えません": "씬 목록에 구성상 역할을 부제로 표시합니다. 꺼도 내용은 삭제되지 않습니다",
  "転換情報": "무대 전환 정보",
  "転換中に演者を歩かせる": "전환 중 출연자가 걷게 하기",
  "ONでは演者の移動・入り・はけを歩いて表示します。OFFでは演者が次のシーンの配置へすぐ切り替わります。大道具・照明・暗転の転換は続きます": "켜면 출연자의 이동·등장·퇴장을 걷는 동작으로 표시합니다. 끄면 출연자가 다음 씬의 배치로 즉시 바뀝니다. 대도구·조명·암전의 전환은 계속됩니다",
  "平面図の照明機材の白い枠を表示": "평면도에서 조명기구의 흰색 윤곽 표시",
  "楽器に合わせて自動": "악기에 맞춰 자동 설정",
  "選択中のシーンの上下に、転換の長さ・暗転・メモを表示する。OFFでも内容は消えません": "선택한 씬의 위아래에 전환 길이·암전·메모를 표시합니다. 꺼도 내용은 삭제되지 않습니다",
  "選択中のシーンの上下に、次のシーンへの移動時間・暗転・メモを表示する。OFFでも内容は消えません": "선택한 씬의 위아래에 다음 씬으로 이동하는 시간·암전·메모를 표시합니다. 꺼도 내용은 삭제되지 않습니다",
  "シーンの左右ミラー": "씬 좌우 반전",
  "シーン操作に「ミラー」が出て、いまのシーンを上手下手そっくり反転する": "씬 작업에 ‘반전’이 표시되고 현재 씬을 상수와 하수 방향으로 완전히 뒤집습니다",
  "整列（横・縦・斜め・円・V字・逆V字）": "정렬(가로·세로·대각선·원·V자·역V자)",
  "シーン操作に整列ボタンが出て、舞台上の演者を並べ直す": "씬 작업에 정렬 버튼이 나타나며 무대 위 출연자를 다시 배치합니다",
  "転換の忙しさ診断": "전환 작업량 진단",
  "ショー地図に、転換ごとの移動量・動く人数・出入りの数を出す": "공연 지도에 전환별 이동 거리·이동 인원·출입 횟수를 표시합니다",
  "同時に動く演者の動線がぶつかりそうな所に、平面図で印を出す": "동시에 움직이는 출연자의 이동 경로가 충돌할 수 있는 곳을 평면도에 표시합니다",
  "高所の下の注意": "높은 장비 아래 주의",
  "ポールやトラピーズの真下に人が居るとき、平面図に印を出す": "폴이나 트라페즈 바로 아래에 사람이 있으면 평면도에 표시합니다",
  "引いた絵を軽くする": "멀리 보이는 그림 단순화",
  "アリーナ・ドームなど大きい会場の3Dカメラで、遠くの客席を簡単に描いて動きを軽くする。近くの見え方は変わりません": "아레나·돔 등 큰 공연장의 3D 카메라에서 멀리 있는 객석을 단순하게 그려 동작을 가볍게 합니다. 가까운 곳의 모습은 바뀌지 않습니다",
  "バミリ図（印刷）": "무대 표시 위치도(인쇄)",
  "印刷用ページに、演者の立ち位置の実寸表を足す": "인쇄용 페이지에 출연자 위치의 실제 치수표를 추가합니다",
  "明かりのキューシート（印刷）": "조명 Q시트(인쇄)",
  "明かりのQシート（印刷）": "조명 Q시트(인쇄)",
  "印刷用ページに、シーンごとの明かりの点き消え表を足す": "인쇄용 페이지에 씬별 조명 켜짐·꺼짐 표를 추가합니다",
  "小道具の香盤表（印刷）": "소품 사용표(인쇄)",
  "印刷用ページに、シーンごとの持ち手と受け渡しの表を足す": "인쇄용 페이지에 씬별 소품 담당자와 전달 관계를 표시한 표를 추가합니다",
  "見えない席の検査（遮蔽）": "시야가 가려지는 좌석 검사",
  "複数選択と整形": "다중 선택과 정렬",
  "資料棚からのシーン引用": "자료실에서 씬 가져오기",
  "スクリーンの文字": "스크린 글자",
  "例: 三回宙返り / ドン / 10年後": "예: 공중제비 세 번 / 쿵 / 10년 후",
