  "舞台上の演者を、いまの位置関係を保ったまま並べ直す": "무대 위 출연자의 현재 상대적 위치를 유지하며 다시 배치합니다",
  "平面図の「動線を描く」の横に整列のプルダウンが出て、舞台上の演者を並べ直す": "평면도의 ‘이동 경로 그리기’ 옆에 정렬 메뉴가 나타나 무대 위 출연자를 다시 배치합니다",
