  "演者・大道具・きっかけなど、この転換で行うこと": "출연자·무대 장치·신호 등 이 전환에서 할 일",
  "暗転": "암전",
  "このシーンへの転換を、一度真っ暗にしてから明ける": "이 씬으로 전환할 때 한 번 완전히 어둡게 한 뒤 다시 밝힙니다",
  "転換の長さ": "전환 길이",
