  "文字入力中も⌘Sは使えます。ほかの舞台操作は、文字入力を優先します。WindowsとLinuxでは⌘をCtrlに読み替えてください。": "글자를 입력하는 동안에도 ⌘S를 사용할 수 있습니다. 다른 무대 조작보다 글자 입력이 우선됩니다. Windows와 Linux에서는 ⌘ 대신 Ctrl을 사용하세요.",
  "細": "가늘게",
  "行を押してから、割り当てたいキーを押すと変更できます。": "행을 누른 다음, 할당할 키를 누르면 바꿀 수 있습니다.",
  "設定はこの端末・このブラウザにだけ保存されます。": "설정은 이 기기, 이 브라우저에만 저장됩니다.",
