  "ほかの操作": "기타 동작",
  "このキーは決まっていて、変更できません。": "이 키는 정해져 있어 변경할 수 없습니다.",
  "この版では使えません。": "이 버전에서는 사용할 수 없습니다.",
  "キーを押す": "키를 누르세요",
  "Escで取り消し。すでに使われているキーは設定できません。": "Esc로 취소합니다. 이미 사용 중인 키는 지정할 수 없습니다.",
  "{key}は「{name}」に使われています。": "{key} 키는 「{name}」에 사용 중입니다.",
  "{key}はブラウザまたはOSの操作に使われるため設定できません。": "{key} 키는 브라우저 또는 OS 동작에 사용되므로 지정할 수 없습니다.",
  "このキーはショートカットに使えません。別のキーを押してください。": "이 키는 단축키로 쓸 수 없습니다. 다른 키를 누르세요.",
  "{name}を{key}に変更しました。": "「{name}」을(를) {key}(으)로 바꿨습니다.",
  "既定のキーに戻しました。": "기본 단축키로 되돌렸습니다.",
  "舞台タブ": "무대 탭",
