  "作業灯を点ける・消す": "작업등 켜기·끄기",
  "全画面の図を入れ替える": "전체 화면의 도면 교체",
  "キューを送る": "큐 넘기기",
  "太": "굵게",
  "演者名": "출연자 이름",
  "装置名": "장치 이름",
  "入替": "교체",
  "正面と平面を入れ替える": "정면도와 평면도 교체",
  "全画面で正面と平面を入れ替える": "전체 화면에서 정면도와 평면도 교체",
  "表示する図を切り替える（両方表示中は上下順を変更）": "표시할 도면 전환(둘 다 표시 중이면 위아래 순서 변경)",
  "いまの道具の説明": "현재 도구 설명",
  "いまの道具の説明を出す": "현재 도구 설명 표시",
  "演者や物を選び、舞台の上で動かします。平面図は空き地をドラッグして移動し、Shift＋ドラッグで囲い選択できます。": "출연자나 물건을 선택해 무대에서 움직입니다. 평면도의 빈 곳을 드래그하면 화면이 이동하고, Shift를 누른 채 드래그하면 영역을 선택할 수 있습니다.",
  "持ち物は図の上で掴み、演者から離して置けます。": "도면에서 들고 있는 물건을 잡아 출연자에게서 멀리 옮겨 놓을 수 있습니다.",
  "正面図または平面図をなぞると矢印になります。正面図では床の上か空中かを選べます。": "정면도나 평면도에 그리면 화살표가 됩니다. 정면도에서는 바닥 또는 공중을 선택할 수 있습니다.",
  "空中の矢印は正面図で描きます": "공중의 화살표는 정면도에서 그립니다",
  "上下で奥行き、左右で立ち位置を決めます。選択中は矢印キーでも動かせます。": "위아래로 깊이를, 좌우로 서 있는 위치를 정합니다. 선택한 상태에서는 방향키로도 움직일 수 있습니다.",
  "正面": "정면",
  "平面（上から）": "평면(위에서)",
  "両方": "둘 다",
    "下部・二図横並びでは二つの図を同時に表示します。一つだけ表示するには他の並べ方を選んでください": "하단 나란히 배치에서는 두 도면을 동시에 표시합니다. 하나만 표시하려면 다른 배치를 선택하세요.",
    "下部・二図横並びでは二つの図を同時に表示します。": "하단 나란히 배치에서는 두 도면을 동시에 표시합니다.",
    "表示する図。下部・二図横並びでは左から右の順。Tで入れ替え": "표시할 도면. 하단 나란히 배치는 왼쪽부터 오른쪽 순서입니다. T로 교체",
  "正面＋平面": "정면＋평면",
  "平面＋正面": "평면＋정면",
  "表示する図。両方1は正面が上、両方2は平面が上": "표시할 도면입니다. ‘둘 다 1’은 정면도가 위, ‘둘 다 2’는 평면도가 위에 옵니다",
  "表示する図。Tで切替。二図の名前は上から下の順": "표시할 도면입니다. T 키로 전환합니다. 두 도면의 이름은 위에서 아래 순서입니다",
  "どの絵を出すか": "표시할 그림 선택",
  "等倍に戻す": "원래 배율로 되돌리기",
  "拡大": "확대",
