  "カスタム会場の平面。追加ステージ、客席、舞台袖を描きます": "맞춤형 극장의 평면도입니다. 추가 무대·객석·무대 옆 공간을 그립니다",
  "カスタム劇場の平面。追加ステージ、客席、舞台袖を描きます": "맞춤형 극장의 평면도입니다. 추가 무대·객석·무대 옆 공간을 그립니다",
  "平面図の表示倍率": "평면도 표시 배율",
  "必須": "필수",
  "1. ステージの形式を選択してください": "1. 무대 형식을 선택해 주세요",
  "2. メインの形を選択してください": "2. 주 무대 형태를 선택해 주세요",
  "舞台の高さ": "무대 높이",
  "客席の奥行きを実寸で出す": "객석 깊이를 실제 치수로 표시",
  "平面図の客席を、会場の実際の奥行きで止める。奥の縁に線と「客席 ○m」の札を出します": "평면도의 객석을 극장의 실제 깊이까지만 그립니다. 뒤쪽 가장자리에 선과 ‘객석 ○m’ 표시를 추가합니다",
  "衣装を明かりの色で染める": "의상을 조명 색으로 물들여 표시",
  "衣装": "의상",
  "このセクションの衣装": "이 섹션의 의상",
  "衣装を着せる": "의상 입히기",
  "衣装を外す": "의상 벗기기",
  "衣装を着せました。": "의상을 입혔습니다.",
  "衣装を外しました。": "의상을 벗겼습니다.",
  "このセクションで衣装を着せる": "이 섹션에서 의상 입히기",
  "このセクションで衣装を外す": "이 섹션에서 의상 벗기기",
  "このセクションで衣装を着せました。": "이 섹션에서 의상을 입혔습니다.",
  "このセクションで衣装を外しました。": "이 섹션에서 의상을 벗겼습니다.",
  "全員に衣装": "모두에게 의상 입히기",
  "全員の衣装を外す": "모두의 의상 벗기기",
  "このセクションの全員に衣装を着せました。": "이 섹션의 모두에게 의상을 입혔습니다.",
  "このセクションの全員の衣装を外しました。": "이 섹션에 있는 모두의 의상을 벗겼습니다.",
  "このセクションの演者に、それぞれの衣装を着せました。": "이 섹션의 출연자에게 각자의 의상을 다시 입혔습니다.",
  "上衣": "상의",
