// v0.3.30 release notes.
Object.assign(window.SHOSAI_I18N_PACKS["ko"].text, {
  "同梱の見本ショーは、一覧だけを先に読み込み、開くときに本文を読み込むようにして、起動を軽くしました。保存したショーから再開するときは、見本の本文を読みません。": "동봉된 샘플 공연은 목록만 먼저 불러오고, 열 때 내용을 불러오도록 하여 시작을 가볍게 했습니다. 저장한 공연에서 다시 시작할 때는 샘플 내용을 불러오지 않습니다.",
  "起動の軽さ: 照明・進行表・冊子・3D・韓国語と中国語の言葉は、使うときに読み込むようにしました。舞台タブ・劇場設定・保存は、オフラインでもいつでも使えます。": "가벼운 시작: 조명·공연 진행표·사용 안내 책자·3D·한국어와 중국어 언어 팩은 사용할 때 불러오도록 했습니다. 무대 탭·극장 설정·저장은 오프라인에서도 언제든 사용할 수 있습니다.",
  "3D は初めて開くときに読み込みます。読み込みに失敗しても、元の画面と保存した見え方はそのままです。": "3D는 처음 열 때 불러옵니다. 불러오기에 실패해도 원래 화면과 저장한 시점 설정은 그대로 유지됩니다.",
  "表示の言葉は、選んでいる言語と英語だけを先に読み込みます。": "화면의 문구는 선택한 언어와 영어만 먼저 불러옵니다.",
  "現場モード（Studio・Company）: 編集を止めて、GO・次のシーンとキュー・いまのシーンのメモ・経過時間だけを大きく出します。": "공연 모드(Studio·Company): 편집을 막고 GO·다음 씬과 큐·현재 씬의 메모·경과 시간만 크게 표시합니다.",
  "転換が間に合わないかもしれないところに印を出します（移動の距離と転換の秒から必要な速さを計算。目安は設定で変えられます）。": "제시간에 끝나지 못할 수 있는 전환에 표시를 합니다(이동 거리와 전환 시간으로 필요한 속도를 계산하며, 기준은 설정에서 바꿀 수 있습니다).",
  "全体表に「香盤表」の別名を併記し、A4 1枚に収めて印刷できるようにしました。": "전체 표에 「씬 배치표」라는 별칭을 함께 표시하고 A4 한 장에 맞춰 인쇄할 수 있도록 했습니다.",
  "iPad・iPhone 向けの画面が、起動のときに有効にならないことがあったのを直しました。狭い画面で操作のボタンが重ならないようにし、設定の歯車も押せるようにしました。": "iPad·iPhone용 화면이 시작할 때 활성화되지 않는 경우를 수정했습니다. 좁은 화면에서 조작 버튼이 겹치지 않도록 하고 설정 톱니바퀴도 누를 수 있도록 했습니다."
});

