  "選択した進行項目を複製して次に置きます。": "선택한 진행 항목을 복제하여 다음에 놓습니다.",
  "紙面の入力を確定し、現在のショーを保存します。": "지면 입력을 확정하고 현재 공연을 저장합니다.",
  "ブラウザの印刷画面で進行表を印刷・PDF保存します。": "브라우저 인쇄 창에서 진행표를 인쇄하거나 PDF로 저장합니다.",
  "進行表を含むショー全体をファイルへ書き出します。": "진행표를 포함한 공연 전체를 파일로 내보냅니다.",
  "配布する版の内容・変更点・届け先の返答を確認します。": "배포할 버전의 내용·변경점·수신자 답변을 확인합니다.",
  "進行表に表示する列を選びます。": "진행표에 표시할 열을 고릅니다.",
  "画面上の紙を白地・黒地で切り替えます。": "화면의 용지를 흰색·검은색으로 전환합니다.",
  "紙面と印刷の文字サイズを標準の10ptへ戻します。": "지면과 인쇄 글자 크기를 기본 10pt로 되돌립니다.",
  "表の幅・表示倍率・項目一覧の幅を初期値へ戻します。": "표 너비·표시 배율·항목 목록 너비를 초기값으로 되돌립니다.",
  "項目を選ぶための一覧を開閉します。": "항목을 고르는 목록을 열고 닫습니다.",
  "進行表の入力・選択・移動の操作方法を表示します。": "진행표 항목의 입력·선택·이동 방법을 표시합니다.",
  "台本をA4縦の印刷用画面で開きます。": "대본을 A4 세로 인쇄 화면으로 엽니다.",
  "現在の台本を、シーンメモの台本から作り直します。確認後に置き換えます。": "현재 대본을 씬 메모에서 다시 만듭니다. 확인 후 교체합니다.",
  "台本に新しい行を追加します。行を選んでいるときは、その下に入ります。": "대본에 새 줄을 추가합니다. 줄을 선택한 경우 그 아래에 넣습니다.",
  "このシーンの台本の末尾に新しい行を追加します。": "이 씬의 대본 끝에 새 줄을 추가합니다.",
  "この対象のキューシートを画面で確認します。": "이 대상의 큐 시트를 화면에서 확인합니다.",
  "この対象のキューシートを印刷用の画面で開きます。": "이 대상의 큐 시트를 인쇄 화면으로 엽니다.",
  "この対象のキューシートをCSVファイルへ書き出します。": "이 대상의 큐 시트를 CSV 파일로 내보냅니다.",
  "この演者の全項目と出演シーンの舞台図をまとめて開きます。": "이 출연자의 모든 항목과 출연 씬의 무대도를 함께 엽니다.",
