  "書き出すファイル名を揃えました。中身は変わらず、旧い名前のファイルも読み込めます。": "내보내는 파일 이름을 통일했습니다. 내용은 그대로이며 이전 이름의 파일도 불러올 수 있습니다.",
  "版を上げた最初の起動だけ、主な変更点を1行で表示するようにしました。": "업데이트 뒤 처음 실행할 때만 주요 변경점을 한 줄로 표시합니다.",
  "キーボードのTabで、画面の流れに沿って操作へ移れるよう順路を改善しました。": "키보드 Tab 이동 순서가 화면 흐름을 더 잘 따르도록 개선했습니다."
